# We generate UTF-8, NUL-terminated C strings as bytes. These will feed FUZZ_PARAM_STR
# across stubs that expect valid UTF-8 for json_string/json_string_set and also as JSON
# texts for json_loads and as keys for object ops. We keep inputs valid and interesting.

# Helper: build valid UTF-8 code point sequence
def _encode_codepoints(cps):
    s = ''.join(chr(cp) for cp in cps)
    return s.encode('utf-8')

def _interesting_codepoints():
    # Diverse set to cover ASCII, BMP, astral, combining, RTL, emojis, edge cases
    return [
        # ASCII
        0x20, 0x21, 0x2F, 0x30, 0x39, 0x3A, 0x40, 0x41, 0x5A, 0x5B, 0x61, 0x7A, 0x7E,
        # Whitespace and separators
        0x09, 0x0A, 0x0D, 0x20, 0xA0, 0x1680, 0x2000, 0x2001, 0x2003, 0x2028, 0x2029, 0x3000,
        # Punctuation JSON-relevant
        0x22, 0x5C, 0x7B, 0x7D, 0x5B, 0x5D, 0x2C, 0x3A,
        # Accented and combining
        0x00E9, 0x00F1, 0x0101, 0x0301, 0x034F, 0x200D, 0x2060,
        # RTL and direction marks
        0x05D0, 0x0627, 0x202A, 0x202B, 0x202D, 0x202E, 0x2066, 0x2067, 0x2069,
        # Edge BMP
        0x007F, 0x0080, 0x07FF, 0x0800, 0xFFFD,
        # Emojis and astral
        0x1F600, 0x1F602, 0x1F9D1, 0x1F469, 0x1F680, 0x1F4A9, 0x1F3F3, 0xFE0F,
        # CJK and others
        0x4E2D, 0x6587, 0x65E5, 0x672C, 0x56FD,
    ]

def _random_word(rng, min_len=1, max_len=16):
    cps = _interesting_codepoints()
    n = rng.randint(min_len, max_len)
    # Avoid embedded NUL; UTF-8 encoding of selected cps won't create NUL bytes
    seq = [rng.choice(cps) for _ in range(n)]
    return _encode_codepoints(seq)

def _random_ascii_identifier(rng, min_len=1, max_len=16):
    first = rng.choice(list(range(ord('A'), ord('Z')+1)) + list(range(ord('a'), ord('z')+1)) + [0x5F])
    rest_len = rng.randint(min_len-1, max_len-1)
    rest_pool = list(range(ord('A'), ord('Z')+1)) + list(range(ord('a'), ord('z')+1)) + list(range(ord('0'), ord('9')+1)) + [0x5F]
    cps = [first] + [rng.choice(rest_pool) for _ in range(max(0, rest_len))]
    return _encode_codepoints(cps)

def _random_json_scalar(rng):
    choice = rng.randrange(0, 7)
    if choice == 0:
        # integer
        v = rng.randint(-2**31, 2**31-1)
        return str(v).encode('ascii')
    elif choice == 1:
        # real
        # Use repr-like with various formats
        v = rng.uniform(-1e6, 1e6)
        fmt = rng.choice(['{}', '{:.6f}', '{:e}', '{:.0f}'])
        s = fmt.format(v)
        # Ensure at least one decimal or exponent to make it real-like sometimes
        if '.' not in s and 'e' not in s and 'E' not in s:
            s = s + '.0'
        return s.encode('ascii')
    elif choice == 2:
        # true/false
        return rng.choice([b'true', b'false'])
    elif choice == 3:
        # null
        return b'null'
    elif choice == 4:
        # string simple ASCII
        content = _random_word(rng, 0, 10).decode('utf-8')
        # JSON escape quotes/backslashes
        content = content.replace('\\', '\\\\').replace('"', '\\"')
        return ('"' + content + '"').encode('utf-8')
    elif choice == 5:
        # empty array
        return b'[]'
    else:
        # empty object
        return b'{}'

def _random_json_string_value(rng, min_len=0, max_len=40):
    # Produce a JSON-escaped string literal with valid UTF-8
    # Include escape sequences to exercise parser
    s = _random_word(rng, min_len, max_len).decode('utf-8')
    # Inject some escapes occasionally
    inserts = ["\\\\", "\"", "\\/", "\\b", "\\f", "\\n", "\\r", "\\t"]
    # Also inject a couple of \uXXXX for ASCII-safe codepoints
    if rng.random() < 0.5:
        hexcp = rng.choice([0x0000, 0x0008, 0x0009, 0x000A, 0x000D, 0x0022, 0x005C])
        inserts.append('\\u%04X' % hexcp)
    # Randomly interleave
    pieces = []
    for ch in s:
        pieces.append(ch)
        if rng.random() < 0.15:
            pieces.append(rng.choice(inserts))
    joined = ''.join(pieces)
    joined = joined.replace('\\', '\\\\').replace('"', '\\"')
    return ('"' + joined + '"').encode('utf-8')

def _random_json_object(rng, max_pairs=6):
    n = rng.randint(0, max_pairs)
    items = []
    for _ in range(n):
        # keys: valid UTF-8, often ASCII identifiers, sometimes non-ASCII
        if rng.random() < 0.6:
            key = _random_ascii_identifier(rng, 1, 12).decode('utf-8')
        else:
            key = _random_word(rng, 1, 8).decode('utf-8')
        key = key.replace('\\', '\\\\').replace('"', '\\"')
        key_lit = '"' + key + '"'
        # value: recursive but shallow to stay under size
        v_choice = rng.random()
        if v_choice < 0.35:
            val = _random_json_scalar(rng)
        elif v_choice < 0.7:
            val = _random_json_string_value(rng)
        else:
            # small array
            val = _random_json_array(rng, max_elems=3)
        items.append((key_lit + ':').encode('utf-8') + b' ' + val)
    return b'{' + (b', '.join(items)) + b'}'

def _random_json_array(rng, max_elems=8):
    n = rng.randint(0, max_elems)
    elems = []
    for _ in range(n):
        choice = rng.random()
        if choice < 0.3:
            elems.append(_random_json_scalar(rng))
        elif choice < 0.7:
            elems.append(_random_json_string_value(rng))
        else:
            elems.append(_random_json_object(rng, max_pairs=3))
    return b'[' + b', '.join(elems) + b']'

def _random_json_text(rng):
    # Produce a top-level JSON value to feed json_loads; ensure valid JSON and variety
    choice = rng.randrange(0, 6)
    if choice == 0:
        return _random_json_object(rng, max_pairs=8)
    elif choice == 1:
        return _random_json_array(rng, max_elems=8)
    elif choice == 2:
        return _random_json_string_value(rng)
    elif choice == 3:
        return _random_json_scalar(rng)
    elif choice == 4:
        # "document" with leading/trailing whitespace/newlines to exercise parser flags
        core = _random_json_object(rng, max_pairs=4)
        ws = rng.choice([b"\n", b"\r\n", b"\t ", b" ", b"\n\n"]) * rng.randint(0, 2)
        return ws + core + ws
    else:
        # Nested structure
        obj = _random_json_object(rng, max_pairs=4)
        arr = _random_json_array(rng, max_elems=4)
        return b'{"a": ' + obj + b', "b": ' + arr + b'}'

def _random_utf8_string_for_json_string_api(rng):
    # Generate a reasonable UTF-8 string (not JSON-literal), used for json_string/json_string_set
    # Include diverse Unicode, avoid embedded NUL. Keep length moderate.
    parts = []
    total_len = rng.randint(0, 128)
    while len(b''.join(parts)) < total_len:
        if rng.random() < 0.2:
            parts.append(_random_word(rng, 1, 8))
        else:
            parts.append(_random_ascii_identifier(rng, 1, 10))
        # occasionally insert spaces or punctuation
        if rng.random() < 0.3:
            parts.append(rng.choice([b' ', b'-', b'_', b'/', b':', b',', b'.']))
    s = b''.join(parts)[:total_len]
    return s

def _build_nul_terminated(blob: bytes) -> bytes:
    # Ensure there is no embedded NUL already (UTF-8 generation avoids it)
    if b"\x00" in blob:
        blob = blob.replace(b"\x00", b"?")
    return blob + b"\x00"

def _choose_mode(rng):
    # Different payload themes to target different stubs using FUZZ_PARAM_STR
    # 0: UTF-8 for json_string/json_string_set
    # 1: JSON text for json_loads
    # 2: Key-like strings for object set APIs
    # 3: Very short edge cases
    # 4: Large but valid UTF-8 within 4KB limit
    return rng.randrange(0, 5)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    mode = _choose_mode(rng)
    if mode == 0:
        s = _random_utf8_string_for_json_string_api(rng)
        return _build_nul_terminated(s)[:4096]
    elif mode == 1:
        j = _random_json_text(rng)
        return _build_nul_terminated(j)[:4096]
    elif mode == 2:
        # Construct a sequence of plausible object keys separated by NULs? FUZZ_PARAM_STR returns one string,
        # so we make a single key-like string with diverse characters
        parts = []
        count = rng.randint(1, 6)
        for _ in range(count):
            if rng.random() < 0.7:
                parts.append(_random_ascii_identifier(rng, 1, 12))
            else:
                parts.append(_random_word(rng, 1, 6))
            if rng.random() < 0.6:
                parts.append(rng.choice([b'.', b':', b'-', b'/', b' ']))
        s = b''.join(parts)[:512]
        return _build_nul_terminated(s)
    elif mode == 3:
        # Edge cases: empty, whitespace, punctuation-heavy
        samples = [
            b"", b" ", b"\t", b"\n", b"null", b"true", b"false",
            b"{}", b"[]", b"\"\"", b"\"a\"", b"{\"k\":123}", b"[1,2,3]",
            _encode_codepoints([0x00E9, 0x0301]),  # e + combining acute
            _encode_codepoints([0x1F600]),         # emoji
            b"\\/\\\\\"",
        ]
        s = rng.choice(samples)
        return _build_nul_terminated(s)
    else:
        # Large UTF-8 text (no NUL), mixed words to exercise path length/keys/strings
        chunks = []
        target = rng.randint(512, 3500)
        while len(b''.join(chunks)) < target:
            if rng.random() < 0.5:
                chunks.append(_random_word(rng, 2, 12))
            else:
                chunks.append(_random_ascii_identifier(rng, 2, 16))
            chunks.append(rng.choice([b' ', b'\n', b'\t', b'-', b'/', b':']))
        s = b''.join(chunks)[:target]
        return _build_nul_terminated(s)

import random
import json
from typing import List

# Generator for producing interesting, valid buffers for Jansson fuzz stubs.
# Focus: FUZZ_PARAM_STR (arbitrary bytes/JSON texts) and FUZZ_PARAM_FILENAME.
# Fixes: ensure recursion is strictly bounded to avoid unbounded mutual recursion.

MAX_TOTAL = 4096

WHITESPACE_PATTERNS = [
    " ", "\t", "\n", "\r", "\n\n", "\t \t", "\r\n",
]

ESCAPE_FRAGMENTS = [
    "\\\"",  # escaped quote
    "\\\\",  # backslash
    "\\/",    # slash
    "\\b", "\\f", "\\n", "\\r", "\\t",
    "\\u00A9", "\\u20AC", "\\uD834\\uDD1E",  # copyright, euro, surrogate pair
]

ARBITRARY_BYTES_SETS: List[bytes] = [
    bytes([0x00, 0xFF, 0x7F, 0x80, 0x01, 0x02, 0x1B]),
    b"\x00middle\x00end",
    b"\xF0\x9F\x92\xA9",  # UTF-8 poop emoji
    b"\xC3\x28",           # invalid UTF-8 sequence
    b"\xED\xA0\x80",      # isolated high surrogate in UTF-8 (invalid)
    b"NUL\x00NUL",
]

JSON_LITERALS = ["true", "false", "null"]

KEY_SAMPLES = [
    "a", "key", "long_key_name", "k1", "dup", "unicode_€", "escape_\"quote\"",
]

NUMBER_SAMPLES = [
    "0", "-0", "1", "-1", "1234567890", "-9223372036854775808", "9223372036854775807",
    "3.14159", "-2.71828", "1e10", "-1E-10", "0.0000001", "1.0000000000000002",
]

STRING_SAMPLES = [
    "", "simple", "with space", "tab\tsep", "line\nfeed", "carriage\rreturn",
    "quote\"inside\"", "backslash\\here", "slash/escape", "control\u0001",
]


def rand_ws(r: random.Random) -> str:
    return r.choice(WHITESPACE_PATTERNS) if r.random() < 0.6 else ""


def rand_escapes(r: random.Random, count: int) -> str:
    # Non-recursive; bounded count
    if count <= 0:
        return ""
    chosen = []
    for _ in range(min(count, 8)):
        chosen.append(r.choice(ESCAPE_FRAGMENTS))
    return "".join(chosen)


def json_string_literal(r: random.Random) -> str:
    base = r.choice(STRING_SAMPLES)
    base += rand_escapes(r, r.randint(0, 3))
    if r.random() < 0.5:
        base += " " + r.choice(["\u00E9", "\u2603", "\u0416"])  # unicode escapes
    return '"' + base + '"'


def json_number_literal(r: random.Random) -> str:
    return r.choice(NUMBER_SAMPLES)


def json_leaf_value(r: random.Random) -> str:
    # Only non-recursive JSON value types
    t = r.randint(0, 3)
    if t == 0:
        return json_string_literal(r)
    if t == 1:
        return json_number_literal(r)
    return r.choice(JSON_LITERALS)


def json_value(r: random.Random, depth: int) -> str:
    # Strictly bounded recursion: when depth <= 0, return a leaf
    if depth <= 0:
        return json_leaf_value(r)
    # Choose among leaf/object/array with bias toward leaves as depth decreases
    roll = r.random()
    if roll < 0.5:
        return json_leaf_value(r)
    elif roll < 0.75:
        return json_array_value(r, depth - 1)
    else:
        return json_object_value(r, depth - 1)


def json_array_value(r: random.Random, depth: int) -> str:
    n = r.randint(0, 6)
    elems = []
    for _ in range(n):
        elems.append(rand_ws(r) + json_value(r, depth) + rand_ws(r))
    return "[" + (",".join(elems)) + "]"


def json_object_value(r: random.Random, depth: int) -> str:
    n = r.randint(0, 6)
    pairs = []
    used = set()
    for _ in range(n):
        if r.random() < 0.3 and ("dup" in used or r.random() < 0.2):
            key = "dup"
        else:
            key = r.choice(KEY_SAMPLES)
            used.add(key)
        key_json = json.dumps(key)
        val = json_value(r, depth)
        pairs.append(rand_ws(r) + f"{key_json}:{rand_ws(r)}{val}" + rand_ws(r))
    return "{" + (",".join(pairs)) + "}"


def make_valid_json_documents(r: random.Random) -> List[bytes]:
    docs: List[bytes] = []
    # Depth limited to avoid recursion explosion
    docs.append(json_object_value(r, 2).encode('utf-8'))
    docs.append(json_array_value(r, 2).encode('utf-8'))
    docs.append(json_string_literal(r).encode('utf-8'))
    docs.append(json_number_literal(r).encode('utf-8'))
    docs.append(r.choice(JSON_LITERALS).encode('utf-8'))

    pretty_obj = json_object_value(r, 2)
    docs.append((rand_ws(r) + pretty_obj + rand_ws(r)).encode('utf-8'))

    nested = '{"mix": ' + json_array_value(r, 2) + ', "inner": ' + json_object_value(r, 1) + '}'
    docs.append(nested.encode('utf-8'))

    return docs


def make_arbitrary_segments(r: random.Random) -> List[bytes]:
    segs: List[bytes] = []
    for _ in range(r.randint(2, 5)):
        choice = r.randint(0, 4)
        if choice == 0:
            segs.append(r.choice(ARBITRARY_BYTES_SETS))
        elif choice == 1:
            count = r.randint(5, 20)
            b = bytearray()
            for _ in range(count):
                if r.random() < 0.2:
                    b.append(0)
                else:
                    b.append(r.randint(32, 126))
            segs.append(bytes(b))
        elif choice == 2:
            size = r.randint(1, 64)
            segs.append(bytes(r.getrandbits(8) for _ in range(size)))
        elif choice == 3:
            pat = r.choice([b"AB\x00", b"\xFF\x00\xFF", b"xyz"]) * r.randint(1, 10)
            segs.append(pat)
        else:
            s = "mix:" + r.choice(["é", "雪", "🙂"]) + " end"
            segs.append(s.encode('utf-8') + b"\xC0\xAF")
    return segs


def assemble_buffer(segments: List[bytes], r: random.Random) -> bytes:
    out = bytearray()
    for i, seg in enumerate(segments):
        if i:
            out.extend(b"\n")
        out.extend(seg)
    if r.random() < 0.7:
        out.extend(b"\n")
        nums = [str(r.getrandbits(16)) for _ in range(r.randint(1, 4))]
        out.extend(" ".join(nums).encode('ascii'))
    return bytes(out[:MAX_TOTAL])


def generate(seed: int) -> bytes:
    r = random.Random(seed)

    segments: List[bytes] = []
    segments.extend(make_valid_json_documents(r))
    segments.extend(make_arbitrary_segments(r))

    path_bases = [
        b"/tmp/fuzz.json", b"/tmp/data.txt", b"input.json", b"data.bin",
        b"/dev/null", b"/tmp/space name.json",
    ]
    r.shuffle(path_bases)
    segments.extend(path_bases[:r.randint(2, 4)])

    return assemble_buffer(segments, r)
